// "Journal" fixtures: trades exactly as the Mac app stores them (every field, including the
// annotations no import format carries: tags, emotion, checklist, costs, sector …).
// The Swift harness builds `Trade` values from these and inserts them through the app's
// own repository, so storage validation applies as it would on the Mac.
import type { FxTrade } from "./fx.ts";
import type { StTrade } from "./st.ts";
import { iso } from "./time.ts";

export const FICTIONAL_NOTE =
  "Fictional data generated by tools/fixture-gen. Not real trades, accounts or people.";

function json(value: unknown): string {
  return JSON.stringify(value, null, 1) + "\n";
}

export function fxJournal(trades: readonly FxTrade[]): string {
  return json({
    note: FICTIONAL_NOTE,
    brand: "dojix",
    trades: trades.map((t) => ({ ...t, openTime: iso(t.openTime), closeTime: iso(t.closeTime) })),
  });
}

export function stJournal(trades: readonly StTrade[]): string {
  return json({
    note: FICTIONAL_NOTE,
    brand: "greenwick",
    trades: trades.map((t) => ({ ...t, openTime: iso(t.openTime), closeTime: iso(t.closeTime) })),
  });
}

/** A hand-written trade list where some fields are deliberately invalid (raw JSON values). */
export function rawJournal(brand: "dojix" | "greenwick", trades: readonly Record<string, unknown>[]): string {
  return json({ note: FICTIONAL_NOTE, brand, trades });
}
